INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002c7',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss urban sociology at B2","Use Stadtsoziologie vocabulary","Talk about urbanisation, gentrification, and city life in Germany"],"explanation":{"intro":"Urban sociology vocabulary covers urbanisation, city planning, and social dynamics of German cities at B2.","culturalNote":"Stadtsoziologie: Germany: Urbanisierungsgrad (urbanisation rate) ~77%. Key cities: Berlin (3.6m), Hamburg (1.9m), Munich (1.6m), Cologne. Key sociologist: Georg Simmel (''Die Großstadt und das Geistesleben'' — ''The Metropolis and Mental Life'' — 1903 — blasé attitude, money economy, individualisation). Robert Park, Chicago School (social ecology of the city). Key concepts: Gentrifizierung (gentrification — rising rents displacing residents), Segregation, Quartier (neighbourhood), soziale Mischung (social mix), Stadtentwicklung (urban development). Key German urban policy: Soziale Stadt (Social City programme — deprived neighbourhoods). Shrinking cities (Schrumpfende Städte — East Germany — Ostdeutschland — population loss). Berlin as global city of culture vs. affordable housing crisis."},"examples":[{"german":"Die Großstadt ist nicht nur ein physischer Raum, sondern eine soziale Wirklichkeit, die eigene psychische Strukturen erzeugt: Simmels ''blasierte Einstellung'' beschreibt eine Abstumpfung gegenüber Reizen und Menschen als Schutzmechanismus angesichts der intensiven Stimulation städtischen Lebens — eine Einstellung, die gleichzeitig Freiheit und Anonymität begünstigt.","english":"The metropolis is not only a physical space but a social reality that generates its own psychic structures: Simmel''s ''blasé attitude'' describes a dulling towards stimuli and people as a protective mechanism in the face of the intense stimulation of urban life — an attitude that simultaneously favours freedom and anonymity."},{"german":"Gentrifizierung ist ein strukturelles Phänomen, kein moralisches: Wenn gut verdienende Haushalte in benachteiligte Stadtteile ziehen, steigen Mieten und Bodenpreise — ein Prozess, der die bisherigen Bewohner verdrängt, obwohl keiner der einzelnen Akteure Verdrängung intendiert. Die Lösung liegt deshalb nicht in individuellen Moralappellen, sondern in wohnungspolitischen Regulierungsinstrumenten.","english":"Gentrification is a structural phenomenon, not a moral one: when high-earning households move into disadvantaged neighbourhoods, rents and land prices rise — a process that displaces existing residents, although none of the individual actors intends displacement. The solution therefore lies not in individual moral appeals, but in housing policy regulatory instruments."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Simmel''s urban theory, gentrification, and German city sociology at B2."}}',
'{"items":[{"word":"die Abstumpfung","translation":"dulling/numbing","pronunciation":"dee AB-shtoom-pfoong","example":"Abstumpfung gegenüber Reizen."},{"word":"begünstigen","translation":"to favour/promote","pronunciation":"beh-GÜN-sti-gen","example":"Anonymität begünstigen."},{"word":"verdrängen","translation":"to displace","pronunciation":"fer-DRENG-en","example":"Bewohner verdrängen."},{"word":"intendieren","translation":"to intend","pronunciation":"in-ten-DEE-ren","example":"Verdrängung intendieren."},{"word":"der Morallappell","translation":"moral appeal","pronunciation":"dayr mo-RAL-ah-pel","example":"Individuelle Moralappelle."},{"word":"wohnungspolitisch","translation":"housing policy (adj.)","pronunciation":"VOH-noonks-po-li-tish","example":"Wohnungspolitische Instrumente."}]}',
'{"title":"X ist ein strukturelles Phänomen, kein moralisches — X is a structural phenomenon, not a moral one","pattern":"X ist ein strukturelles Phänomen, kein moralisches = X is a structural phenomenon, not a moral one (ellipsis: kein moralisches [Phänomen] — the noun is dropped; marks a shift from individual blame to systemic analysis)","explanation":"Strukturell vs. moralisch: The pattern shifts analytical level from individual/moral to structural/systemic. Gentrifizierung ist ein strukturelles Phänomen, kein moralisches = Gentrification is a structural phenomenon, not a moral one. This reframes who is responsible: not individual actors with bad intentions, but the system of incentives and constraints they act within. Key grammar: kein moralisches [Phänomen] — adjective nominalization with ellipsis of the noun (neuter adjective ending -es after kein). Compare: systemisch vs. individuell (systemic vs. individual), strukturell bedingt (structurally caused), nicht auf Böswilligkeit zurückführbar (not traceable to malice).","examples":[{"sentence":"Arbeitslosigkeit ist ein strukturelles Problem, kein individuelles.","translation":"Unemployment is a structural problem, not an individual one."},{"sentence":"Die Krise ist ein systemisches Versagen, kein persönliches.","translation":"The crisis is a systemic failure, not a personal one."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Verdrängen'' means?","options":["to displace","to push out","to oust","to evict"],"correctAnswer":"to displace"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Gentrification is a structural phenomenon, not a moral one: when high-earning households move into disadvantaged neighbourhoods, rents and land prices rise — a process that displaces existing residents, although none of the individual actors intends displacement.","options":["Gentrifizierung ist ein strukturelles Phänomen, kein moralisches: Wenn gut verdienende Haushalte in benachteiligte Stadtteile ziehen, steigen Mieten und Bodenpreise — ein Prozess, der die bisherigen Bewohner verdrängt, obwohl keiner der einzelnen Akteure Verdrängung intendiert.","Gentrifizierung entsteht, wenn Reiche in arme Stadtteile ziehen und Mieten steigen.","Gentrifizierung ist kein moralisches Problem, weil niemand absichtlich verdrängt.","Steigende Mieten verdrängen ärmere Bewohner aus ihren Stadtvierteln."],"correctAnswer":"Gentrifizierung ist ein strukturelles Phänomen, kein moralisches: Wenn gut verdienende Haushalte in benachteiligte Stadtteile ziehen, steigen Mieten und Bodenpreise — ein Prozess, der die bisherigen Bewohner verdrängt, obwohl keiner der einzelnen Akteure Verdrängung intendiert."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Arbeitslosigkeit ist ein strukturelles Problem, kein ___.","options":["individuelles","persönliches","moralisches","privates"],"correctAnswer":"individuelles"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The crisis is a systemic failure not a personal one","wordBankItems":["Die","Krise","ist","ein","systemisches","Versagen",",","kein","persönliches","."],"correctAnswer":"Die Krise ist ein systemisches Versagen , kein persönliches ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Begünstigen'' means?","options":["to favour/promote","to support","to encourage","to facilitate"],"correctAnswer":"to favour/promote"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002c8',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss rural space at B2","Use Ländlicher Raum vocabulary","Talk about rural-urban disparities, Abwanderung, and East German rural decline"],"explanation":{"intro":"Rural space vocabulary covers Germany''s rural-urban gap, demographic decline in rural areas, and policy responses at B2.","culturalNote":"Ländlicher Raum: Germany: Zentrum-Peripherie-Gefälle (centre-periphery gap) — Berlin/Munich vs. rural East Germany. Key: Abwanderung (emigration — especially of young people and women from East — Braindrain). Leerstand (vacancy — empty buildings). Grundversorgung (basic provision — supermarket, doctor, school — disappearing). Strukturwandel (structural change — coal regions: Lausitz, Ruhr). Engagierte Bürgerinnen (committed citizens — local initiatives — ''Dorfkümmerer''). Digital divide (rural broadband gap). Bundesraumordnung (federal spatial planning). Key concept: Gleichwertigkeit der Lebensverhältnisse (equivalence of living conditions — Art. 72 GG — constitutional aspiration). Germany''s post-unification challenge: East German towns still recovering 30+ years later."},"examples":[{"german":"Der ländliche Raum ist kein homogenes Gebilde: Es gibt prosperrende Landgemeinden in der Nähe von Agglomerationszentren und strukturschwache Regionen, die mit Bevölkerungsrückgang, Infrastrukturverlust und wirtschaftlicher Abkopplung kämpfen. Die Gleichwertigkeit der Lebensverhältnisse bleibt ein verfassungsrechtliches Versprechen, das strukturpolitisch eingelöst werden muss.","english":"Rural space is not a homogeneous entity: there are prospering rural communities near agglomeration centres and structurally weak regions fighting population decline, loss of infrastructure, and economic decoupling. The equivalence of living conditions remains a constitutional promise that must be redeemed through structural policy."},{"german":"Abwanderung aus ländlichen Regionen erzeugt eine Spirale des Verfalls: Wenn junge Menschen und Fachkräfte wegziehen, sinkt die Nachfrage nach lokalen Dienstleistungen, was Geschäfte und Einrichtungen schließen lässt, was wiederum die Attraktivität für den Verbleib weiter mindert — ein sich selbstverstärkender Prozess, der ohne aktive Intervention schwer zu stoppen ist.","english":"Out-migration from rural regions creates a spiral of decay: when young people and skilled workers leave, demand for local services falls, causing businesses and facilities to close, which in turn further diminishes attractiveness for remaining — a self-reinforcing process that is hard to stop without active intervention."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Germany''s rural-urban divide, Abwanderung, and structural policy at B2."}}',
'{"items":[{"word":"prosperierend","translation":"prospering","pronunciation":"pros-peh-REE-rend","example":"Prosperierende Gemeinde."},{"word":"die Abkopplung","translation":"decoupling","pronunciation":"dee AB-kop-loong","example":"Wirtschaftliche Abkopplung."},{"word":"einlösen","translation":"to redeem/fulfil","pronunciation":"YN-lö-zen","example":"Versprechen einlösen."},{"word":"mindert","translation":"diminishes","pronunciation":"MIN-dert","example":"Attraktivität mindern."},{"word":"sich selbstverstärkend","translation":"self-reinforcing","pronunciation":"zikh ZELPS-fer-shterk-end","example":"Selbstverstärkender Prozess."},{"word":"die Abwanderung","translation":"out-migration","pronunciation":"dee AB-van-deh-roong","example":"Abwanderung aus Dörfern."}]}',
'{"title":"Sich selbstverstärkend — self-reinforcing (describing feedback loops)","pattern":"ein sich selbstverstärkender Prozess = a self-reinforcing process (sich selbstverstärkend — reflexive present participle: stärkt...sich selbst; modifies a noun as an adjective; describes a feedback loop in which an effect amplifies its own cause)","explanation":"Sich selbstverstärkend = self-reinforcing (present participle of sich selbst verstärken — to amplify itself). Ein sich selbstverstärkender Prozess = a self-reinforcing process. Grammar: the present participle (verstärkend) is used as an attributive adjective and declines like one (selbstverstärkender Prozess — masculine). Other variants: sich selbst tragende Entwicklung (self-sustaining development — similar), Teufelskreis (vicious circle — more colloquial), Feedbackschleife (feedback loop — more technical/English loan). Compare: Sich gegenseitig verstärkend (mutually reinforcing — two separate elements), kumulativ (cumulative — accumulating effect), eskalierend (escalating — getting worse).","examples":[{"sentence":"Armut ist oft ein sich selbstverstärkender Zustand.","translation":"Poverty is often a self-reinforcing state."},{"sentence":"Vertrauen erzeugt einen sich selbstverstärkenden Kreislauf.","translation":"Trust creates a self-reinforcing cycle."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Abkopplung'' means?","options":["decoupling","detachment","disconnection","separation"],"correctAnswer":"decoupling"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Out-migration from rural regions creates a spiral of decay: when young people and skilled workers leave, demand for local services falls, causing businesses and facilities to close, which in turn further diminishes attractiveness for remaining — a self-reinforcing process that is hard to stop without active intervention.","options":["Abwanderung aus ländlichen Regionen erzeugt eine Spirale des Verfalls: Wenn junge Menschen und Fachkräfte wegziehen, sinkt die Nachfrage nach lokalen Dienstleistungen, was Geschäfte und Einrichtungen schließen lässt, was wiederum die Attraktivität für den Verbleib weiter mindert — ein sich selbstverstärkender Prozess, der ohne aktive Intervention schwer zu stoppen ist.","Wenn Menschen ländliche Gebiete verlassen, verschlechtert sich die Infrastruktur weiter.","Abwanderung führt zu weniger Dienstleistungen, was wiederum mehr Abwanderung auslöst.","Ländliche Regionen geraten in eine Abwärtsspirale, wenn Fachkräfte wegziehen."],"correctAnswer":"Abwanderung aus ländlichen Regionen erzeugt eine Spirale des Verfalls: Wenn junge Menschen und Fachkräfte wegziehen, sinkt die Nachfrage nach lokalen Dienstleistungen, was Geschäfte und Einrichtungen schließen lässt, was wiederum die Attraktivität für den Verbleib weiter mindert — ein sich selbstverstärkender Prozess, der ohne aktive Intervention schwer zu stoppen ist."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Armut ist oft ein sich ___ Zustand.","options":["selbstverstärkender","selbsterhaltender","selbstproduzierender","selbstgenerierender"],"correctAnswer":"selbstverstärkender"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Trust creates a self-reinforcing cycle","wordBankItems":["Vertrauen","erzeugt","einen","sich","selbstverstärkenden","Kreislauf","."],"correctAnswer":"Vertrauen erzeugt einen sich selbstverstärkenden Kreislauf ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Einlösen'' means?","options":["to redeem/fulfil","to honour","to deliver on","to cash in"],"correctAnswer":"to redeem/fulfil"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002c9',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss migration and integration at B2","Use Migration und Integration vocabulary","Talk about Germany''s migration history, policy, and integration debate"],"explanation":{"intro":"Migration and integration vocabulary covers Germany''s migration history, current policy, and the integration debate at B2.","culturalNote":"Migration und Integration: Germany: a nation of immigration that long denied it. Key history: Gastarbeiter (guest workers — 1955–1973 — Italy, Spain, Turkey, Yugoslavia — ''temporary'' became permanent). Aussiedler (ethnic German repatriates from Eastern Europe). Asylbewerber (asylum seekers). Flüchtlingswelle 2015 (refugee wave — 890,000 in 2015 — Syria, Afghanistan, Iraq). Key policy: Aufenthaltsgesetz (Residence Act), Integrationskurse (integration courses — German language + civic knowledge). Key debate: Multikulti vs. Leitkultur (multicultural vs. dominant culture). Failed integration (Erdogan vs. Merkel — ''Multikulti ist kläglich gescheitert'' — 2010). Deutsches Staatsbürgerschaftsrecht reform (2024 — dual citizenship now possible). Fachkräftemangel (skilled worker shortage — Germany needs 400k migrants/year). Key distinction: Integration vs. Assimilation vs. Inklusion."},"examples":[{"german":"Integration ist kein einmaliger Akt, sondern ein wechselseitiger Prozess: Er verlangt von Zugewanderten die Bereitschaft, die Grundregeln der Aufnahmegesellschaft anzuerkennen, und von der Aufnahmegesellschaft die Bereitschaft, Zugewanderten gleiche Teilhabechancen zu ermöglichen — ein Anspruch, der sowohl individuelle Leistung als auch strukturelle Öffnung fordert.","english":"Integration is not a one-time act but a reciprocal process: it demands from immigrants a readiness to recognise the basic rules of the host society, and from the host society a readiness to enable immigrants equal participation opportunities — a claim that demands both individual effort and structural opening."},{"german":"Die Geschichte der Bundesrepublik zeigt, dass Einwanderungsgesellschaft und nationale Identität keine unvereinbaren Gegensätze sind: Deutschland ist durch Einwanderung nicht weniger deutsch geworden, aber vielschichtiger, kosmopolitischer und wirtschaftlich dynamischer — eine Entwicklung, die Herausforderungen schafft, aber keine Bedrohung der kulturellen Kontinuität darstellt.","english":"The history of the Federal Republic shows that immigration society and national identity are not irreconcilable opposites: Germany has not become less German through immigration, but more layered, more cosmopolitan, and more economically dynamic — a development that creates challenges but does not represent a threat to cultural continuity."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Germany''s Gastarbeiter history, integration policy, and current migration debate at B2."}}',
'{"items":[{"word":"wechselseitig","translation":"reciprocal","pronunciation":"VEKH-zel-zy-tikh","example":"Wechselseitiger Prozess."},{"word":"die Bereitschaft","translation":"readiness/willingness","pronunciation":"dee beh-RYT-shaft","example":"Bereitschaft zeigen."},{"word":"anerkennen","translation":"to recognise","pronunciation":"AN-er-ken-en","example":"Grundregeln anerkennen."},{"word":"vielschichtig","translation":"layered/complex","pronunciation":"FEEL-shikh-tikh","example":"Vielschichtige Gesellschaft."},{"word":"kosmopolitisch","translation":"cosmopolitan","pronunciation":"kos-mo-po-LEE-tish","example":"Kosmopolitischere Stadt."},{"word":"unvereinbar","translation":"irreconcilable","pronunciation":"oon-fer-YN-bahr","example":"Unvereinbare Gegensätze."}]}',
'{"title":"Weder X noch Y sind unvereinbare Gegensätze — X and Y are not irreconcilable opposites","pattern":"X und Y sind keine unvereinbaren Gegensätze = X and Y are not irreconcilable opposites (keine = not/no — negation; unvereinbar = irreconcilable — adjective; Gegensätze = opposites — plural)","explanation":"Keine unvereinbaren Gegensätze = not irreconcilable opposites (keine + neuter/strong adj + plural noun). The pattern pushes back against a false dilemma — the claim that X and Y cannot coexist. Einwanderungsgesellschaft und nationale Identität sind keine unvereinbaren Gegensätze = Immigration society and national identity are not irreconcilable opposites. Alternative formulations: kein Widerspruch (no contradiction), vereinbar (compatible — adjective), miteinander vereinbar (compatible with each other), sich nicht gegenseitig ausschließen (not mutually exclusive — stronger logical formulation).","examples":[{"sentence":"Wettbewerb und Kooperation sind keine unvereinbaren Gegensätze.","translation":"Competition and cooperation are not irreconcilable opposites."},{"sentence":"Freiheit und Gleichheit sind in der Praxis keine unvereinbaren Werte.","translation":"Freedom and equality are not irreconcilable values in practice."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Wechselseitig'' means?","options":["reciprocal","mutual","bilateral","interactive"],"correctAnswer":"reciprocal"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Integration is not a one-time act but a reciprocal process: it demands from immigrants a readiness to recognise the basic rules of the host society, and from the host society a readiness to enable immigrants equal participation opportunities — a claim that demands both individual effort and structural opening.","options":["Integration ist kein einmaliger Akt, sondern ein wechselseitiger Prozess: Er verlangt von Zugewanderten die Bereitschaft, die Grundregeln der Aufnahmegesellschaft anzuerkennen, und von der Aufnahmegesellschaft die Bereitschaft, Zugewanderten gleiche Teilhabechancen zu ermöglichen — ein Anspruch, der sowohl individuelle Leistung als auch strukturelle Öffnung fordert.","Integration ist ein gegenseitiger Prozess, der Anstrengungen auf beiden Seiten erfordert.","Integration gelingt nur, wenn Einwanderer und Aufnahmegesellschaft beide ihren Teil beitragen.","Integration ist keine Einbahnstraße."],"correctAnswer":"Integration ist kein einmaliger Akt, sondern ein wechselseitiger Prozess: Er verlangt von Zugewanderten die Bereitschaft, die Grundregeln der Aufnahmegesellschaft anzuerkennen, und von der Aufnahmegesellschaft die Bereitschaft, Zugewanderten gleiche Teilhabechancen zu ermöglichen — ein Anspruch, der sowohl individuelle Leistung als auch strukturelle Öffnung fordert."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Wettbewerb und Kooperation sind keine ___ Gegensätze.","options":["unvereinbaren","irreconcilablen","absoluten","totalen"],"correctAnswer":"unvereinbaren"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Freedom and equality are not irreconcilable values in practice","wordBankItems":["Freiheit","und","Gleichheit","sind","in","der","Praxis","keine","unvereinbaren","Werte","."],"correctAnswer":"Freiheit und Gleichheit sind in der Praxis keine unvereinbaren Werte ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Anerkennen'' means?","options":["to recognise","to acknowledge","to accept","to validate"],"correctAnswer":"to recognise"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002ca',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss multiculturalism at B2","Use Multikulturalismus vocabulary","Talk about multicultural theories, Germany''s Leitkultur debate, and pluralism"],"explanation":{"intro":"Multiculturalism vocabulary covers theories of cultural pluralism, Germany''s Leitkultur debate, and models of diversity at B2.","culturalNote":"Multikulturalismus: Three models of immigrant integration: Assimilation (France — Republican model — private culture, public French identity), Multiculturalism (UK/Canada — group rights — cultural preservation), Differential exclusion (Germany''s old Gastarbeiter model — neither/nor). Germany: Leitkultur debate (2000 — Friedrich Merz — ''core culture'' that immigrants should assimilate to). Multikulti-Debatte: Angela Merkel (2010 — ''multikulturellen Gesellschaft ist kläglich gescheitert'' — failed multiculturalism). Key thinker: Charles Taylor (Multikulturalismus und die Politik der Anerkennung — recognition politics). Bassam Tibi (Euro-Islam — integration through core values). Will Kymlicka (Liberal multiculturalism — minority rights within liberal framework). Key concept: Parallelgesellschaften (parallel societies) — sociological concept that became politically charged."},"examples":[{"german":"Multikulturalismus ist kein eindeutiger Begriff, sondern eine Familie von Positionen: Die normative Forderung nach Anerkennung kultureller Differenzen, das soziologische Faktum kultureller Pluralität und die politische Strategie gruppenspezifischer Rechte werden häufig vermengt, obwohl sie analytisch sauber zu trennen sind.","english":"Multiculturalism is not a univocal concept but a family of positions: the normative demand for recognition of cultural differences, the sociological fact of cultural plurality, and the political strategy of group-specific rights are frequently conflated, although they can be cleanly separated analytically."},{"german":"Die Leitkulturdebatte enthüllt ein grundlegendes Spannungsverhältnis: Ohne gemeinsame Grundwerte funktioniert keine Demokratie, aber die Bestimmung dieser Grundwerte ist selbst ein umstrittener politischer Prozess — wer die Leitkultur definiert, übt kulturelle Deutungsmacht aus, die nicht neutral ist.","english":"The Leitkultur debate reveals a fundamental tension: without shared fundamental values, no democracy functions, but the determination of these values is itself a contested political process — whoever defines the core culture exercises cultural interpretive power that is not neutral."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss multiculturalism theory, Germany''s Leitkultur debate, and Taylor''s recognition politics at B2."}}',
'{"items":[{"word":"eindeutig","translation":"univocal/unambiguous","pronunciation":"YN-doy-tikh","example":"Kein eindeutiger Begriff."},{"word":"vermengen","translation":"to conflate/mix up","pronunciation":"fer-MENG-en","example":"Begriffe vermengen."},{"word":"sauber trennen","translation":"to cleanly separate","pronunciation":"ZOW-ber TREN-en","example":"Analytisch sauber trennen."},{"word":"das Spannungsverhältnis","translation":"tension relationship","pronunciation":"dahs SHPAN-noonks-fer-hält-nis","example":"Grundlegendes Spannungsverhältnis."},{"word":"die Deutungsmacht","translation":"interpretive power","pronunciation":"dee DOY-toonks-makht","example":"Kulturelle Deutungsmacht."},{"word":"umstritten","translation":"contested","pronunciation":"oom-SHRIT-en","example":"Umstrittener Prozess."}]}',
'{"title":"X vermengen, obwohl analytisch sauber zu trennen — conflating X although analytically separable","pattern":"etwas vermengt X, obwohl sie analytisch sauber zu trennen sind = something conflates X, although they can be cleanly separated analytically (vermengen = to conflate/mix; obwohl = although — concessive; analytisch sauber = analytically clean; zu + infinitive as modal equivalent: ''can be'')","explanation":"Vermengen = to conflate, mix up (implies inappropriate/confused mixing). Obwohl analytisch sauber zu trennen = although cleanly separable analytically (zu + infinitive after adjective = modal meaning ''can be/is able to be'': zu trennen = separable = can be separated). The pattern describes conceptual confusion: different things that are frequently lumped together but should be kept analytically distinct. This is a common move in German academic discourse. Compare: gleichsetzen (to equate), verwechseln (to confuse), auf einen Nenner bringen (to reduce to a common denominator), unterscheiden (to distinguish — the solution to conflation).","examples":[{"sentence":"Ursache und Wirkung werden häufig vermengt, obwohl analytisch klar zu trennen.","translation":"Cause and effect are frequently conflated, although analytically clearly separable."},{"sentence":"Die Begriffe werden vermengt, obwohl sie analytisch verschieden sind.","translation":"The concepts are conflated, although they are analytically different."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Vermengen'' means?","options":["to conflate/mix up","to confuse","to blur","to combine"],"correctAnswer":"to conflate/mix up"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Multiculturalism is not a univocal concept but a family of positions: the normative demand for recognition of cultural differences, the sociological fact of cultural plurality, and the political strategy of group-specific rights are frequently conflated, although they can be cleanly separated analytically.","options":["Multikulturalismus ist kein eindeutiger Begriff, sondern eine Familie von Positionen: Die normative Forderung nach Anerkennung kultureller Differenzen, das soziologische Faktum kultureller Pluralität und die politische Strategie gruppenspezifischer Rechte werden häufig vermengt, obwohl sie analytisch sauber zu trennen sind.","Multikulturalismus bedeutet verschiedene Dinge: Pluralismus, Anerkennung und Gruppenrechte.","Der Begriff Multikulturalismus wird zu unscharf verwendet.","Normative, soziologische und politische Dimensionen von Multikulturalismus sind zu unterscheiden."],"correctAnswer":"Multikulturalismus ist kein eindeutiger Begriff, sondern eine Familie von Positionen: Die normative Forderung nach Anerkennung kultureller Differenzen, das soziologische Faktum kultureller Pluralität und die politische Strategie gruppenspezifischer Rechte werden häufig vermengt, obwohl sie analytisch sauber zu trennen sind."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ursache und Wirkung werden häufig vermengt, obwohl analytisch klar zu ___.","options":["trennen","unterscheiden","separieren","differenzieren"],"correctAnswer":"trennen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The concepts are conflated although they are analytically different","wordBankItems":["Die","Begriffe","werden","vermengt",",","obwohl","sie","analytisch","verschieden","sind","."],"correctAnswer":"Die Begriffe werden vermengt , obwohl sie analytisch verschieden sind ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Deutungsmacht'' means?","options":["interpretive power","definitional authority","interpretive authority","meaning power"],"correctAnswer":"interpretive power"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002cb',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss racism and discrimination at B2","Use Rassismus und Diskriminierung vocabulary","Talk about structural racism, the NSU scandal, and antidiscrimination law in Germany"],"explanation":{"intro":"Racism and discrimination vocabulary covers structural racism, the NSU trial, and Germany''s antidiscrimination framework at B2.","culturalNote":"Rassismus und Diskriminierung: Germany: long denial of racism as structural problem (''Wir sind nicht rassistisch''). Key event: NSU (Nationalsozialistischer Untergrund — far-right terrorist network — 10 murders 2000–2006 — victims: 9 Turkish-Germans, 1 Greek-German, 2 police officers — police initially blamed victim families). NSU-Skandal triggered reckoning. Allgemeines Gleichbehandlungsgesetz (AGG — General Equal Treatment Act 2006 — implements EU directives — prohibits discrimination by race, gender, religion, disability, age, sexual orientation). Rassismuskritik (critical race studies). Racial profiling. BLM movement impact on Germany 2020. Key concept: Struktureller Rassismus (structural racism — systemic rather than intentional). Postmigrantische Gesellschaft (post-migrant society — Naika Foroutan). Alltagsrassismus (everyday racism — microaggressions)."},"examples":[{"german":"Struktureller Rassismus unterscheidet sich von individuellem Vorurteil dadurch, dass er keine rassistischen Absichten voraussetzt: Institutionen, Gesetze und soziale Praktiken können benachteiligend wirken, auch wenn keine ihrer Akteure bewusst diskriminieren will — der Maßstab ist Ergebnis, nicht Intention.","english":"Structural racism differs from individual prejudice in that it does not presuppose racist intentions: institutions, laws, and social practices can have a disadvantaging effect, even if none of their actors consciously wants to discriminate — the standard is outcome, not intention."},{"german":"Antidiskriminierungsrecht schützt nicht nur Individuen, sondern kodiert gesellschaftliche Normen: Indem es bestimmte Unterscheidungsmerkmale als verbotene Diskriminierungsgrundlagen ausweist, gibt es an, welche Differenzen in einer Gesellschaft als legitim gelten und welche Gleichbehandlung als normativ geboten betrachtet wird.","english":"Antidiscrimination law protects not only individuals, but encodes societal norms: by designating certain distinguishing characteristics as prohibited bases of discrimination, it indicates which differences are regarded as legitimate in a society and what equal treatment is normatively considered required."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss structural racism, the NSU scandal, and Germany''s antidiscrimination law at B2."}}',
'{"items":[{"word":"das Vorurteil","translation":"prejudice","pronunciation":"dahs FOR-oor-tyl","example":"Individuelles Vorurteil."},{"word":"voraussetzen","translation":"to presuppose","pronunciation":"for-OWS-set-tsen","example":"Absichten voraussetzen."},{"word":"benachteiligend","translation":"disadvantaging","pronunciation":"beh-NAKHH-ty-li-gend","example":"Benachteiligend wirken."},{"word":"das Merkmal","translation":"characteristic/criterion","pronunciation":"dahs MERK-mahl","example":"Unterscheidungsmerkmal."},{"word":"ausweisen als","translation":"to designate as","pronunciation":"OWS-vy-zen als","example":"Als verboten ausweisen."},{"word":"normativ geboten","translation":"normatively required","pronunciation":"nor-mah-TEEF geh-BOH-ten","example":"Normativ gebotene Gleichbehandlung."}]}',
'{"title":"X unterscheidet sich von Y dadurch, dass Z — X differs from Y in that Z (contrastive definition)","pattern":"X unterscheidet sich von Y dadurch, dass Z = X differs from Y in that Z (dadurch, dass = in that/by the fact that — marks the dimension of difference; dass + subordinate clause describes the relevant distinguishing feature)","explanation":"Sich unterscheiden von + dadurch, dass = to differ from...in that... (dadurch, dass introduces the substance of the difference). Struktureller Rassismus unterscheidet sich von individuellem Vorurteil dadurch, dass er keine rassistischen Absichten voraussetzt = Structural racism differs from individual prejudice in that it does not presuppose racist intentions. The pattern is used for contrastive definitions: it names two things (X and Y) and gives the key distinguishing feature (Z). Compare: im Gegensatz zu X (in contrast to X — preposition), während X...Y (while X...Y — temporal/contrastive clause), nicht X, sondern Y (not X but Y — simpler replacement).","examples":[{"sentence":"Demokratie unterscheidet sich von Autokratie dadurch, dass Macht rechenschaftspflichtig ist.","translation":"Democracy differs from autocracy in that power is accountable."},{"sentence":"Kontrakt unterscheidet sich von Vertrauen dadurch, dass er erzwingbar ist.","translation":"Contract differs from trust in that it is enforceable."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Das Vorurteil'' means?","options":["prejudice","bias","stereotype","preconception"],"correctAnswer":"prejudice"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Structural racism differs from individual prejudice in that it does not presuppose racist intentions: institutions, laws, and social practices can have a disadvantaging effect, even if none of their actors consciously wants to discriminate — the standard is outcome, not intention.","options":["Struktureller Rassismus unterscheidet sich von individuellem Vorurteil dadurch, dass er keine rassistischen Absichten voraussetzt: Institutionen, Gesetze und soziale Praktiken können benachteiligend wirken, auch wenn keine ihrer Akteure bewusst diskriminieren will — der Maßstab ist Ergebnis, nicht Intention.","Struktureller Rassismus braucht keine rassistischen Menschen — er ist in Strukturen eingebaut.","Auch ohne rassistische Absicht können Strukturen diskriminierend wirken.","Der Maßstab für Rassismus ist das Ergebnis, nicht die Absicht."],"correctAnswer":"Struktureller Rassismus unterscheidet sich von individuellem Vorurteil dadurch, dass er keine rassistischen Absichten voraussetzt: Institutionen, Gesetze und soziale Praktiken können benachteiligend wirken, auch wenn keine ihrer Akteure bewusst diskriminieren will — der Maßstab ist Ergebnis, nicht Intention."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Demokratie unterscheidet sich von Autokratie dadurch, dass Macht ___ ist.","options":["rechenschaftspflichtig","transparent","kontrollierbar","begrenzt"],"correctAnswer":"rechenschaftspflichtig"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Contract differs from trust in that it is enforceable","wordBankItems":["Kontrakt","unterscheidet","sich","von","Vertrauen","dadurch",",","dass","er","erzwingbar","ist","."],"correctAnswer":"Kontrakt unterscheidet sich von Vertrauen dadurch , dass er erzwingbar ist ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Voraussetzen'' means?","options":["to presuppose","to assume","to require","to take for granted"],"correctAnswer":"to presuppose"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002cc',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss nationalism and populism at B2","Use Nationalismus und Populismus vocabulary","Talk about the rise of AfD, populist movements, and democratic backsliding in Germany"],"explanation":{"intro":"Nationalism and populism vocabulary covers the definition of populism, Germany''s AfD, and democratic resilience at B2.","culturalNote":"Nationalismus und Populismus: Key: Jan-Werner Müller (''Was ist Populismus?'' — 2016 — populists claim exclusive legitimacy: ''only we represent the true people''). Thin ideology (Cas Mudde — populism + host ideology). Germany: AfD (Alternative für Deutschland — founded 2013 — liberal economics → ethnonationalism — 2024 Bundestag election: 20.8%). Verfassungsschutzbeobachtung (observed by domestic intelligence). Identitäre Bewegung. Höcke (Thuringia — ''Flügel'' — officially dissolved). Key concept: Nativismus (nativism — ethnic exclusivism — ''das Volk'' = ethnic not civic). Democratic backsliding (demokratischer Rückfall — Hungary, Poland — warning for Germany). Wehrhafte Demokratie (militant democracy — Art. 18, 21 GG — Parteienverbot). Key phrase: Populismus als antipluralistisch (anti-pluralist) — anti-minority."},"examples":[{"german":"Populismus ist eine schlanke Ideologie, die andere Weltanschauungen als Wirt benötigt: Die Behauptung, das ''wahre Volk'' gegen eine korrupte Elite zu vertreten, kann mit Nationalismus, Sozialismus oder religiösem Fundamentalismus kombiniert werden — was Populismus von Rechtsextremismus unterscheidet, ist nicht die Intensität, sondern die Offenheit für verschiedene ideologische Inhalte.","english":"Populism is a thin ideology that needs other worldviews as a host: the claim to represent the ''true people'' against a corrupt elite can be combined with nationalism, socialism, or religious fundamentalism — what distinguishes populism from right-wing extremism is not intensity, but openness to various ideological contents."},{"german":"Wehrhafte Demokratie setzt voraus, dass demokratische Systeme gegen ihre Feinde aktiv verteidigt werden dürfen: Das Bundesverfassungsgericht kann Parteien verbieten, die auf die Abschaffung der freiheitlichen Grundordnung abzielen — eine Schranke, die nicht gegen unliebsame Meinungen, sondern gegen aktive Verfassungsfeinde gedacht ist.","english":"Militant democracy presupposes that democratic systems may be actively defended against their enemies: the Federal Constitutional Court can ban parties that aim at the abolition of the free democratic basic order — a barrier conceived not against unwelcome opinions, but against active enemies of the constitution."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Jan-Werner Müller''s populism theory, the AfD, and Germany''s Wehrhafte Demokratie at B2."}}',
'{"items":[{"word":"schlank","translation":"thin/lean","pronunciation":"shlank","example":"Schlanke Ideologie."},{"word":"der Wirt","translation":"host (biology/ideology)","pronunciation":"dayr VEERT","example":"Ideologie als Wirt."},{"word":"korrupt","translation":"corrupt","pronunciation":"ko-ROOPT","example":"Korrupte Elite."},{"word":"die Schranke","translation":"barrier","pronunciation":"dee SHRANK-eh","example":"Verfassungsschranke."},{"word":"unliebsam","translation":"unwelcome","pronunciation":"oon-LEEP-zahm","example":"Unliebsame Meinungen."},{"word":"abzielen auf","translation":"to aim at","pronunciation":"AB-tsee-len owf","example":"Auf Abschaffung abzielen."}]}',
'{"title":"X unterscheidet sich durch nicht-Y, sondern Z — distinguished not by Y but by Z","pattern":"was X von Y unterscheidet, ist nicht Z, sondern W = what distinguishes X from Y is not Z, but W (embedded question used as subject; nicht...sondern = not...but — two competing characterisations with correction)","explanation":"Was X von Y unterscheidet, ist nicht Z, sondern W = What distinguishes X from Y is not Z but W. Embedded question (was...unterscheidet) as subject of the sentence. The pattern distinguishes a concept from a common misconception: it names the false criterion (Z) and replaces it with the correct one (W). Was Populismus von Rechtsextremismus unterscheidet, ist nicht die Intensität, sondern die Offenheit = What distinguishes populism from right-wing extremism is not intensity, but openness. Compare: der Unterschied zwischen X und Y liegt nicht in Z, sondern in W (the difference lies not in Z but in W), X unterscheidet sich von Y nicht durch Z, sondern durch W (X differs from Y not through Z but through W).","examples":[{"sentence":"Was Kunst von Handwerk unterscheidet, ist nicht die Technik, sondern die Intention.","translation":"What distinguishes art from craft is not the technique, but the intention."},{"sentence":"Was Respekt von Konformität unterscheidet, ist nicht das Verhalten, sondern sein Ursprung.","translation":"What distinguishes respect from conformity is not the behaviour, but its origin."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Unliebsam'' means?","options":["unwelcome","undesirable","unpleasant","unfavourable"],"correctAnswer":"unwelcome"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Populism is a thin ideology that needs other worldviews as a host: the claim to represent the ''true people'' against a corrupt elite can be combined with nationalism, socialism, or religious fundamentalism — what distinguishes populism from right-wing extremism is not intensity, but openness to various ideological contents.","options":["Populismus ist eine schlanke Ideologie, die andere Weltanschauungen als Wirt benötigt: Die Behauptung, das ''wahre Volk'' gegen eine korrupte Elite zu vertreten, kann mit Nationalismus, Sozialismus oder religiösem Fundamentalismus kombiniert werden — was Populismus von Rechtsextremismus unterscheidet, ist nicht die Intensität, sondern die Offenheit für verschiedene ideologische Inhalte.","Populismus braucht eine andere Ideologie als Grundlage.","Populismus ist flexibler als Rechtsextremismus, weil er verschiedene Inhalte annehmen kann.","Der Unterschied zwischen Populismus und Rechtsextremismus liegt in der ideologischen Offenheit."],"correctAnswer":"Populismus ist eine schlanke Ideologie, die andere Weltanschauungen als Wirt benötigt: Die Behauptung, das ''wahre Volk'' gegen eine korrupte Elite zu vertreten, kann mit Nationalismus, Sozialismus oder religiösem Fundamentalismus kombiniert werden — was Populismus von Rechtsextremismus unterscheidet, ist nicht die Intensität, sondern die Offenheit für verschiedene ideologische Inhalte."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Was Kunst von Handwerk unterscheidet, ist nicht die Technik, sondern die ___.","options":["Intention","Absicht","Bedeutung","Aussage"],"correctAnswer":"Intention"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: What distinguishes respect from conformity is not the behaviour but its origin","wordBankItems":["Was","Respekt","von","Konformität","unterscheidet",",","ist","nicht","das","Verhalten",",","sondern","sein","Ursprung","."],"correctAnswer":"Was Respekt von Konformität unterscheidet , ist nicht das Verhalten , sondern sein Ursprung ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Abzielen auf'' means?","options":["to aim at","to target","to intend","to seek"],"correctAnswer":"to aim at"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002cd',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss antisemitism at B2","Use Antisemitismus vocabulary","Talk about Germany''s special responsibility, contemporary antisemitism, and remembrance"],"explanation":{"intro":"Antisemitism vocabulary covers Germany''s Erinnerungskultur, contemporary antisemitism forms, and the legal/political response at B2.","culturalNote":"Antisemitismus: Germany has special historical responsibility (besondere Verantwortung) for the Shoah. Key legal: Leugnung des Holocaust (Holocaust denial — §130 StGB — criminal). Volksverhetzung (incitement to hatred — also criminalised). Key institution: Beauftragter der Bundesregierung für jüdisches Leben (Commissioner for Jewish Life). Contemporary forms: Primärer Antisemitismus (ideological — conspiracy theories), Sekundärer Antisemitismus (memory-related — guilt defence — ''Schlussstrich''-demand), Israelischer Antisemitismus (anti-Zionism sliding into antisemitism — Israelbezogener Antisemitismus). Zentralrat der Juden in Deutschland (Central Council of Jews in Germany). October 7 2023 Hamas attack triggered surge in antisemitic incidents in Germany (+300%). Key concept: Nie wieder (Never again — German constitutional commitment since 1949 — contested meaning in post-Oct 7 context). Stolpersteine (stumbling stones — Gunter Demnig — memorial project)."},"examples":[{"german":"Deutschlands besondere Verantwortung gegenüber dem jüdischen Volk erwächst aus dem Zivilisationsbruch des Holocaust: Das ''Nie wieder'' ist kein historisches Ritual, sondern eine lebendige politische Verpflichtung, die in jede Entscheidung einwirkt, die den Schutz jüdischen Lebens, die Bekämpfung von Antisemitismus und die Unterstützung des Staates Israel berührt.","english":"Germany''s special responsibility towards the Jewish people grows from the civilisational rupture of the Holocaust: ''Never again'' is not a historical ritual but a living political obligation that bears on every decision that touches the protection of Jewish life, the combating of antisemitism, and the support for the state of Israel."},{"german":"Zeitgenössischer Antisemitismus ist vielgestaltig: Neben klassischen Verschwörungstheorien existieren schuldabwehrende Formen, die die Einzigartigkeit des Holocaust relativieren, um der deutschen Verantwortung zu entkommen, und israelfeindliche Formen, die legitime Kritik an israelischer Politik mit antisemitischen Stereotypen vermengen.","english":"Contemporary antisemitism is multifaceted: alongside classical conspiracy theories, there exist guilt-deflecting forms that relativise the uniqueness of the Holocaust to escape German responsibility, and anti-Israel forms that conflate legitimate criticism of Israeli policy with antisemitic stereotypes."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Germany''s Holocaust responsibility, forms of contemporary antisemitism, and ''Nie wieder'' at B2."}}',
'{"items":[{"word":"erwachsen aus","translation":"to grow from","pronunciation":"er-VAKS-en owss","example":"Verantwortung erwächst aus."},{"word":"der Zivilisationsbruch","translation":"civilisational rupture","pronunciation":"dee tsee-vi-li-ZA-tsyohns-brukhh","example":"Zivilisationsbruch."},{"word":"einwirken auf","translation":"to bear on","pronunciation":"YN-vir-ken owf","example":"In Entscheidungen einwirken."},{"word":"vielgestaltig","translation":"multifaceted","pronunciation":"FEEL-geh-shtal-tikh","example":"Vielgestaltiger Antisemitismus."},{"word":"schuldabwehrend","translation":"guilt-deflecting","pronunciation":"SHOOLT-ab-vay-rend","example":"Schuldabwehrender Antisemitismus."},{"word":"relativieren","translation":"to relativise","pronunciation":"reh-lah-tee-VEE-ren","example":"Einzigartigkeit relativieren."}]}',
'{"title":"Erwächst aus X — grows from X (obligation/responsibility arising from history)","pattern":"etwas erwächst aus X = something grows from/out of X (erwachsen aus = to grow from, arise from — present: erwächst — irregular; aus + dative = from; marks the historical or moral source of an obligation or responsibility)","explanation":"Erwachsen aus = to grow from, arise from (irregular: erwächst — 3rd person singular present). Deutschlands Verantwortung erwächst aus dem Zivilisationsbruch = Germany''s responsibility grows from the civilisational rupture. The phrase marks the moral or historical source of an obligation: not a chosen responsibility, but one arising necessarily from historical events. Compare: sich ableiten aus (to derive from — more logical/theoretical), resultieren aus (to result from — more causal/neutral), folgen aus (to follow from — logical consequence), hervorgehen aus (to emerge from — more process-based).","examples":[{"sentence":"Aus diesem Versprechen erwachsen konkrete Pflichten.","translation":"From this promise, concrete duties grow."},{"sentence":"Die Pflicht zur Fürsorge erwächst aus dem Vertrauen.","translation":"The duty of care grows from the trust."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Relativieren'' means?","options":["to relativise","to downplay","to minimise","to contextualise"],"correctAnswer":"to relativise"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Germany''s special responsibility towards the Jewish people grows from the civilisational rupture of the Holocaust: ''Never again'' is not a historical ritual but a living political obligation that bears on every decision that touches the protection of Jewish life, the combating of antisemitism, and the support for the state of Israel.","options":["Deutschlands besondere Verantwortung gegenüber dem jüdischen Volk erwächst aus dem Zivilisationsbruch des Holocaust: Das ''Nie wieder'' ist kein historisches Ritual, sondern eine lebendige politische Verpflichtung, die in jede Entscheidung einwirkt, die den Schutz jüdischen Lebens, die Bekämpfung von Antisemitismus und die Unterstützung des Staates Israel berührt.","Deutschland hat wegen der Holocaust-Geschichte eine besondere Verantwortung gegenüber Juden.","''Nie wieder'' bedeutet, dass Deutschland Antisemitismus und Bedrohungen Israels bekämpft.","Die Erinnerung an den Holocaust verpflichtet Deutschland zu aktivem Schutz jüdischen Lebens."],"correctAnswer":"Deutschlands besondere Verantwortung gegenüber dem jüdischen Volk erwächst aus dem Zivilisationsbruch des Holocaust: Das ''Nie wieder'' ist kein historisches Ritual, sondern eine lebendige politische Verpflichtung, die in jede Entscheidung einwirkt, die den Schutz jüdischen Lebens, die Bekämpfung von Antisemitismus und die Unterstützung des Staates Israel berührt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Aus diesem Versprechen erwachsen konkrete ___.","options":["Pflichten","Verpflichtungen","Aufgaben","Verantwortungen"],"correctAnswer":"Pflichten"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The duty of care grows from the trust","wordBankItems":["Die","Pflicht","zur","Fürsorge","erwächst","aus","dem","Vertrauen","."],"correctAnswer":"Die Pflicht zur Fürsorge erwächst aus dem Vertrauen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Einwirken auf'' means?","options":["to bear on","to influence","to affect","to impact"],"correctAnswer":"to bear on"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002ce',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss postcolonialism at B2","Use Postkolonialismus vocabulary","Talk about German colonialism, postcolonial theory, and decolonisation debates"],"explanation":{"intro":"Postcolonialism vocabulary covers Germany''s colonial past, postcolonial theory, and current decolonisation debates at B2.","culturalNote":"Postkolonialismus: Germany: colonial power 1884–1919 (Deutsch-Ostafrika, Deutsch-Südwestafrika, Kamerun, Togo). Herero and Nama genocide (1904–1908 — Deutsch-Südwestafrika — acknowledged by Germany as Völkermord 2021 — reparations negotiations). Key figure: Edward Said (Orientalism 1978 — Western representations of the ''Orient'' as constructed to serve colonial power). Spivak (''Can the Subaltern Speak?''). Bhabha (hybridity). Germany: contested colonial memory — Kolonialzeit vs. Kolonialverbrechen. Dekolonisierung (decolonisation) of museums: Humboldt Forum controversy (Benin bronzes — looted from Nigeria — returned 2022). Postkoloniale Studien (postcolonial studies in Germany — relatively recent). ''Koloniales Erbe'' (colonial legacy) in German language: Schnitzel from Schnitt — Zimt from Persian — many Arabic loan words."},"examples":[{"german":"Postkoloniale Theorie zeigt, dass Kolonialismus nicht nur ein politisch-ökonomisches System war, sondern auch ein epistemisches: Er produzierte Wissensordnungen, Repräsentationen und Selbstverständnisse, die das kolonisierte Andere als primitiv, irrational und steuerungsbedürftig konstruierten und damit die moralische Rechtfertigung für Ausbeutung und Gewalt lieferten.","english":"Postcolonial theory shows that colonialism was not only a political-economic system, but also an epistemic one: it produced orders of knowledge, representations, and self-understandings that constructed the colonised Other as primitive, irrational, and in need of direction, thereby supplying the moral justification for exploitation and violence."},{"german":"Die Forderung nach Dekolonisierung von Museen und Kulturerbe ist keine Frage des guten Willens, sondern des Eigentumsrechts: Objekte, die unter kolonialen Bedingungen — Raub, ungleiche Tauschverhältnisse, Zwang — in europäische Sammlungen gelangt sind, wurden nicht rechtmäßig erworben und unterliegen Rückgabeansprüchen, die durch historische Distanz nicht verjähren.","english":"The demand for decolonisation of museums and cultural heritage is not a question of goodwill, but of property rights: objects that reached European collections under colonial conditions — plunder, unequal exchange relations, coercion — were not lawfully acquired and are subject to restitution claims that do not expire through historical distance."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss postcolonial theory, Germany''s colonial legacy, and the Benin bronzes debate at B2."}}',
'{"items":[{"word":"epistemisch","translation":"epistemic","pronunciation":"eh-pis-TAY-mish","example":"Epistemisches System."},{"word":"die Ausbeutung","translation":"exploitation","pronunciation":"dee OWS-boy-toong","example":"Koloniale Ausbeutung."},{"word":"steuerungsbedürftig","translation":"in need of direction","pronunciation":"SHTOY-eh-roonks-beh-dürf-tikh","example":"Als steuerungsbedürftig konstruiert."},{"word":"der Zwang","translation":"coercion","pronunciation":"dayr TSVANG","example":"Kolonialer Zwang."},{"word":"verjähren","translation":"to expire/lapse (statute of limitations)","pronunciation":"fer-YÄ-ren","example":"Ansprüche verjähren nicht."},{"word":"die Rückgabe","translation":"restitution","pronunciation":"dee RÜK-gah-beh","example":"Rückgabe von Kulturgütern."}]}',
'{"title":"Unterliegen Rückgabeansprüchen, die durch X nicht verjähren — subject to restitution claims that do not expire through X","pattern":"etwas unterliegt einem Anspruch, der durch X nicht verjährt = something is subject to a claim that does not expire through X (unterliegen + dative = to be subject to; verjähren = to lapse/expire — legal term for statute of limitations; durch X nicht verjähren = does not expire through X)","explanation":"Unterliegen + dative = to be subject to (formal/legal). Verjähren = to expire (legal: statute of limitations runs out — Verjährungsfrist = limitation period). Rückgabeansprüche, die durch historische Distanz nicht verjähren = restitution claims that do not expire through historical distance. The pattern makes a legal argument: the right of restitution persists despite time. Compare: einem Anspruch ausgesetzt sein (to be exposed to a claim — more informal), einen Anspruch haben (to have a claim — subject''s perspective), rechtmäßig erworben (lawfully acquired — addresses the title).","examples":[{"sentence":"Menschenrechtsverletzungen unterliegen Verfolgungsansprüchen, die nicht verjähren.","translation":"Human rights violations are subject to prosecution claims that do not expire."},{"sentence":"Das Eigentum unterliegt einem Rückgabeanspruch, der nicht verjährt.","translation":"The property is subject to a restitution claim that does not expire."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Ausbeutung'' means?","options":["exploitation","abuse","oppression","suppression"],"correctAnswer":"exploitation"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The demand for decolonisation of museums and cultural heritage is not a question of goodwill, but of property rights: objects that reached European collections under colonial conditions — plunder, unequal exchange relations, coercion — were not lawfully acquired and are subject to restitution claims that do not expire through historical distance.","options":["Die Forderung nach Dekolonisierung von Museen und Kulturerbe ist keine Frage des guten Willens, sondern des Eigentumsrechts: Objekte, die unter kolonialen Bedingungen — Raub, ungleiche Tauschverhältnisse, Zwang — in europäische Sammlungen gelangt sind, wurden nicht rechtmäßig erworben und unterliegen Rückgabeansprüchen, die durch historische Distanz nicht verjähren.","Geraubte Kulturgüter müssen zurückgegeben werden, egal wie viel Zeit vergangen ist.","Die Dekolonisierung von Museen ist eine rechtliche, keine moralische Frage.","Kolonialzeit-Objekte in europäischen Museen haben fragwürdige Eigentumsverhältnisse."],"correctAnswer":"Die Forderung nach Dekolonisierung von Museen und Kulturerbe ist keine Frage des guten Willens, sondern des Eigentumsrechts: Objekte, die unter kolonialen Bedingungen — Raub, ungleiche Tauschverhältnisse, Zwang — in europäische Sammlungen gelangt sind, wurden nicht rechtmäßig erworben und unterliegen Rückgabeansprüchen, die durch historische Distanz nicht verjähren."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Menschenrechtsverletzungen unterliegen Verfolgungsansprüchen, die nicht ___.","options":["verjähren","erlöschen","enden","ablaufen"],"correctAnswer":"verjähren"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The property is subject to a restitution claim that does not expire","wordBankItems":["Das","Eigentum","unterliegt","einem","Rückgabeanspruch",",","der","nicht","verjährt","."],"correctAnswer":"Das Eigentum unterliegt einem Rückgabeanspruch , der nicht verjährt ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Der Zwang'' means?","options":["coercion","force","compulsion","pressure"],"correctAnswer":"coercion"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002cf',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss feminism and gender order at B2","Use Feminismus und Geschlechterordnung vocabulary","Talk about feminist theory, Germany''s gender gap, and the debate on gender equality"],"explanation":{"intro":"Feminism and gender order vocabulary covers feminist theory waves, Germany''s gender pay gap, and current debates at B2.","culturalNote":"Feminismus und Geschlechterordnung: Germany: Gender Pay Gap ~18% (raw) / ~6% (adjusted). Frauenquote (gender quota — supervisory boards — 30% mandatory since 2016). Parité (parity) in politics — debate. Key feminist theory: First wave (suffrage — Hedwig Dohm — 1876 — before UK/US); Second wave (1968 — consciousness raising — reproductive rights — Alice Schwarzer — Emma magazine); Third wave (intersectionality — Kimberlé Crenshaw — 1989 — race+gender); Fourth wave (digital feminism — #MeToo 2017). Gender (soziales Geschlecht) vs. Sex (biologisches Geschlecht — Butler: performativity). Gendern (gender-inclusive language — Genderstern * — Gendern debate in Germany — very controversial). Frauen in Führungspositionen (women in leadership — still underrepresented). Gleichstellungsbeauftragte (equal opportunities officer — mandatory in federal agencies)."},"examples":[{"german":"Feminismus der zweiten Welle analysierte die Unterordnung von Frauen als strukturell: Nicht biologische Differenz, sondern gesellschaftliche Machtverhältnisse seien der Grund, warum Frauen aus dem öffentlichen Leben ausgeschlossen und auf reproduktive Aufgaben beschränkt wurden — eine Einsicht, die das Private als politisch auswies und Hausarbeit als Produktion ohne Marktentlohnung sichtbar machte.","english":"Second-wave feminism analysed the subordination of women as structural: not biological difference, but societal power relations were the reason why women were excluded from public life and restricted to reproductive tasks — an insight that designated the private as political and made housework visible as production without market remuneration."},{"german":"Die Genderdebatte in Deutschland offenbart eine gesellschaftliche Tiefenspannung: Wer Sprache als Abbild gesellschaftlicher Verhältnisse versteht, sieht im Gendern ein symbolisches Instrument zur Sichtbarmachung von Vielfalt; wer Sprache als neutrales Kommunikationsmedium betrachtet, lehnt das Gendern als ideologische Überfrachtung ab — eine Auseinandersetzung, die weit mehr als Grammatik berührt.","english":"The gender debate in Germany reveals a deep social tension: those who understand language as a reflection of social relations see gendering as a symbolic instrument for making diversity visible; those who view language as a neutral medium of communication reject gendering as ideological overloading — a dispute that touches far more than grammar."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss feminist theory waves, Germany''s gender pay gap, and the Gendern debate at B2."}}',
'{"items":[{"word":"die Unterordnung","translation":"subordination","pronunciation":"dee OON-ter-ord-noong","example":"Unterordnung von Frauen."},{"word":"ausweisen als","translation":"to designate as","pronunciation":"OWS-vy-zen als","example":"Das Private als politisch ausweisen."},{"word":"die Überfrachtung","translation":"overloading","pronunciation":"dee ü-ber-FRAKHT-oong","example":"Ideologische Überfrachtung."},{"word":"das Abbild","translation":"reflection/image","pronunciation":"dahs AB-bilt","example":"Abbild der Gesellschaft."},{"word":"die Sichtbarmachung","translation":"making visible","pronunciation":"dee ZIKHT-bahr-makh-oong","example":"Sichtbarmachung von Vielfalt."},{"word":"ablehnen","translation":"to reject","pronunciation":"AB-lay-nen","example":"Gendern ablehnen."}]}',
'{"title":"Wer X versteht, sieht Y als Z; wer X betrachtet als W, lehnt Y als V ab — two perspectives","pattern":"Wer X versteht, sieht Y als Z; wer X als W betrachtet, lehnt Y als V ab = Those who understand X as [framing], see Y as Z; those who view X as W, reject Y as V (wer + verb = those who/whoever; the pattern presents two perspectives non-judgmentally by parallel wer-clauses)","explanation":"Wer + verb (relative/conditional pronoun meaning ''whoever/those who'') — two parallel perspectives. Wer Sprache als Abbild gesellschaftlicher Verhältnisse versteht, sieht...; wer Sprache als neutrales Medium betrachtet, lehnt...ab = Those who understand language as a reflection...see...; those who view language as a neutral medium...reject... The pattern describes a genuine perspective split: two groups who hold different framings reach opposite conclusions from the same phenomenon. It''s analytically neutral — neither side is dismissed. Compare: Während X...Y (While X...Y — temporal/contrastive), Einerseits...andererseits (On one hand...on the other hand — less personal), Je nach Perspektive (Depending on perspective — more adverbial).","examples":[{"sentence":"Wer Arbeit als Pflicht sieht, wird Feierabend anders erleben als wer Arbeit als Berufung versteht.","translation":"Those who see work as duty will experience leisure differently from those who understand work as vocation."},{"sentence":"Wer Kritik als Angriff deutet, reagiert defensiv; wer Kritik als Hilfe versteht, reagiert offen.","translation":"Those who interpret criticism as an attack react defensively; those who understand criticism as help react openly."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Unterordnung'' means?","options":["subordination","subjugation","submission","subjection"],"correctAnswer":"subordination"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The gender debate in Germany reveals a deep social tension: those who understand language as a reflection of social relations see gendering as a symbolic instrument for making diversity visible; those who view language as a neutral medium of communication reject gendering as ideological overloading — a dispute that touches far more than grammar.","options":["Die Genderdebatte in Deutschland offenbart eine gesellschaftliche Tiefenspannung: Wer Sprache als Abbild gesellschaftlicher Verhältnisse versteht, sieht im Gendern ein symbolisches Instrument zur Sichtbarmachung von Vielfalt; wer Sprache als neutrales Kommunikationsmedium betrachtet, lehnt das Gendern als ideologische Überfrachtung ab — eine Auseinandersetzung, die weit mehr als Grammatik berührt.","Die Genderdebatte ist eigentlich eine Debatte über Sprachpolitik.","Gendern wird abgelehnt, weil es Sprache ideologisch überlädt.","Die Debatte über Gendersprache spiegelt tiefere gesellschaftliche Spaltungen wider."],"correctAnswer":"Die Genderdebatte in Deutschland offenbart eine gesellschaftliche Tiefenspannung: Wer Sprache als Abbild gesellschaftlicher Verhältnisse versteht, sieht im Gendern ein symbolisches Instrument zur Sichtbarmachung von Vielfalt; wer Sprache als neutrales Kommunikationsmedium betrachtet, lehnt das Gendern als ideologische Überfrachtung ab — eine Auseinandersetzung, die weit mehr als Grammatik berührt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Wer Arbeit als Pflicht sieht, wird Feierabend anders ___ als wer Arbeit als Berufung versteht.","options":["erleben","wahrnehmen","empfinden","erfahren"],"correctAnswer":"erleben"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Those who interpret criticism as an attack react defensively those who understand it as help react openly","wordBankItems":["Wer","Kritik","als","Angriff","deutet",",","reagiert","defensiv",";","wer","Kritik","als","Hilfe","versteht",",","reagiert","offen","."],"correctAnswer":"Wer Kritik als Angriff deutet , reagiert defensiv ; wer Kritik als Hilfe versteht , reagiert offen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Das Abbild'' means?","options":["reflection/image","picture","mirror","representation"],"correctAnswer":"reflection/image"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002d0',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss queer perspectives at B2","Use Queere Perspektiven vocabulary","Talk about LGBTQ+ rights in Germany, queer theory, and legal progress"],"explanation":{"intro":"Queer perspectives vocabulary covers LGBTQ+ rights in Germany, queer theory, and debates about gender and sexuality at B2.","culturalNote":"Queere Perspektiven: Germany: §175 StGB (criminalisation of male homosexuality — in force 1872–1969 West Germany, 1968 East Germany; continued prosecutions East Germany into 1980s; fully abolished 1994; rehabilitation of convicted men 2017). Ehe für alle (same-sex marriage — legalised 2017 — CDU/CSU voted against). Queer theory: Judith Butler (''Gender Trouble'' — 1990 — gender as performativity — not natural, but produced through repetition). Intersex rights — Germany: third gender option in official documents since 2018. Trans rights debate (Selbstbestimmungsgesetz — Self-Determination Act 2024 — gender marker change by self-declaration). CSD (Christopher Street Day — Cologne, Berlin, Hamburg). Key concept: Heteronormativität (heteronormativity — assumption that heterosexuality is the norm). Queer as umbrella term vs. political identity."},"examples":[{"german":"Queer Theory zeigt, dass Geschlecht keine biologische Gegebenheit, sondern ein performativer Effekt ist: Nach Butler produzieren wiederholte Handlungen, Normen und Diskurse das Geschlecht, das sie scheinbar nur beschreiben — eine Einsicht, die den Status des Natürlichen als ideologische Konstruktion demaskiert und den Spielraum für Genderdissidenz öffnet.","english":"Queer theory shows that gender is not a biological given, but a performative effect: according to Butler, repeated actions, norms, and discourses produce the gender they appear only to describe — an insight that unmasks the status of the natural as an ideological construction and opens the room for gender dissidence."},{"german":"Die Legalisierung der Ehe für alle war ein Meilenstein rechtlicher Gleichstellung, aber kein Ende der Auseinandersetzung: Formale Rechtlichkeit beseitigt weder gesellschaftliche Diskriminierung noch alltagspraktische Benachteiligung — Queere Menschen sind in Deutschland formal rechtlich gleichgestellt, erfahren aber weiterhin Sichtbarkeitslücken, Gewalt und Diskriminierung im privaten wie beruflichen Raum.","english":"The legalisation of same-sex marriage was a milestone of legal equal standing, but not the end of the dispute: formal legality eliminates neither societal discrimination nor everyday practical disadvantage — queer people in Germany are formally legally equal, but still experience visibility gaps, violence, and discrimination in both private and professional spaces."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Butler''s gender performativity, Germany''s LGBTQ+ legal history, and heteronormativity at B2."}}',
'{"items":[{"word":"performativ","translation":"performative","pronunciation":"per-for-mah-TEEF","example":"Performativer Effekt."},{"word":"demaskieren","translation":"to unmask","pronunciation":"deh-mas-KEE-ren","example":"Ideologie demaskieren."},{"word":"die Dissidenz","translation":"dissidence","pronunciation":"dee di-si-DENTS","example":"Genderdissidenz."},{"word":"der Meilenstein","translation":"milestone","pronunciation":"dayr MY-len-shty-ne","example":"Rechtlicher Meilenstein."},{"word":"die Sichtbarkeitslücke","translation":"visibility gap","pronunciation":"dee ZIKHT-bahr-kyts-lü-keh","example":"Sichtbarkeitslücken."},{"word":"beseitigen","translation":"to eliminate","pronunciation":"beh-ZY-ti-gen","example":"Diskriminierung beseitigen."}]}',
'{"title":"Demaskiert als X — unmasked as X (revealing the ideological construction beneath the natural)","pattern":"etwas als X demaskieren = to unmask something as X (demaskieren = to unmask — transitive; als + noun/adjective marks what it is revealed to be; often passive: als X demaskiert werden = to be unmasked as X)","explanation":"Demaskieren = to unmask (from de- + Maske/mask — to reveal what lies behind the mask). Als ideologische Konstruktion demaskiert = unmasked as an ideological construction. The phrase is used critically to reveal that something presented as natural, neutral, or given is actually constructed, ideological, or interested. Compare: entlarven als (to expose/unmask as — stronger emotional charge — implies deception), enthüllen (to reveal — more neutral), bloßlegen (to lay bare — more empirical), dekonstruieren (to deconstruct — more academic/theoretical — Derrida).","examples":[{"sentence":"Die vermeintliche Objektivität wurde als Ideologie demaskiert.","translation":"The supposed objectivity was unmasked as ideology."},{"sentence":"Das vermeintliche Naturgesetz wurde als historisches Konstrukt demaskiert.","translation":"The supposed natural law was unmasked as a historical construct."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Demaskieren'' means?","options":["to unmask","to reveal","to expose","to strip away"],"correctAnswer":"to unmask"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Queer theory shows that gender is not a biological given, but a performative effect: according to Butler, repeated actions, norms, and discourses produce the gender they appear only to describe — an insight that unmasks the status of the natural as an ideological construction and opens the room for gender dissidence.","options":["Queer Theory zeigt, dass Geschlecht keine biologische Gegebenheit, sondern ein performativer Effekt ist: Nach Butler produzieren wiederholte Handlungen, Normen und Diskurse das Geschlecht, das sie scheinbar nur beschreiben — eine Einsicht, die den Status des Natürlichen als ideologische Konstruktion demaskiert und den Spielraum für Genderdissidenz öffnet.","Butler zeigt, dass Geschlecht durch Wiederholung produziert wird, nicht biologisch vorgegeben ist.","Gender ist performativ — durch Handlungen und Diskurse hergestellt, nicht natürlich.","Queer Theory deckt die ideologische Grundlage des ''Natürlichen'' beim Geschlecht auf."],"correctAnswer":"Queer Theory zeigt, dass Geschlecht keine biologische Gegebenheit, sondern ein performativer Effekt ist: Nach Butler produzieren wiederholte Handlungen, Normen und Diskurse das Geschlecht, das sie scheinbar nur beschreiben — eine Einsicht, die den Status des Natürlichen als ideologische Konstruktion demaskiert und den Spielraum für Genderdissidenz öffnet."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die vermeintliche Objektivität wurde als Ideologie ___.","options":["demaskiert","entlarvt","enthüllt","bloßgelegt"],"correctAnswer":"demaskiert"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The supposed natural law was unmasked as a historical construct","wordBankItems":["Das","vermeintliche","Naturgesetz","wurde","als","historisches","Konstrukt","demaskiert","."],"correctAnswer":"Das vermeintliche Naturgesetz wurde als historisches Konstrukt demaskiert ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Beseitigen'' means?","options":["to eliminate","to remove","to abolish","to eradicate"],"correctAnswer":"to eliminate"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

